"""Writes www/js/engbanks.js from built loop banks (lbanks/ID.ogg + lbanks/ID.json).
usage: python3 build_engbanks.py BANKDIR banks.json
banks.json: {"banks": {ID: {"gain": 1, "credit": "..."}}, "by_layout": {...}, "by_engine": {...}, "opts": {...}}"""
import base64, json, os, sys
bdir, cfg = sys.argv[1], json.load(open(sys.argv[2]))
out = ['// ===========================================================================',
       '// ENGINE SAMPLE BANKS - generated by tools/engine_samples/build_engbanks.py.',
       '// Seamless constant-rpm loops cut from recordings of real cars (Wikimedia Commons,',
       '// CC BY 3.0; Internet Archive, CC BY 4.0): credits per bank below and in README.md.',
       '// ===========================================================================',
       '(function () {', '  var DR = globalThis.DR;', '  DR.ENG_BANKS = {']
ids = list(cfg['banks'])
for n, i in enumerate(ids):
    meta = json.load(open(os.path.join(bdir, i + '.json')))
    data = base64.b64encode(open(os.path.join(bdir, i + '.ogg'), 'rb').read()).decode()
    b = cfg['banks'][i]
    out.append('    // %s' % b['credit'])
    out.append('    %s: { k: %s, sr: %d, gain: %s, credit: %s,\n      loops: %s,\n      data: %s }%s' % (
        i, meta['k'], meta['sr'], b.get('gain', 1), json.dumps(b['credit']), json.dumps(meta['loops'], separators=(',', ':')), json.dumps(data), ',' if n < len(ids) - 1 else ''))
out.append('  };')
# real exhaust pops shared by every engine
pc = cfg.get('pops')
if pc and os.path.exists(os.path.join(bdir, 'pops.json')):
    pm = json.load(open(os.path.join(bdir, 'pops.json')))
    pdata = base64.b64encode(open(os.path.join(bdir, 'pops.ogg'), 'rb').read()).decode()
    out.append('  // %s' % pc['credit'])
    out.append('  DR.ENG_POPS = { sr: %d, credit: %s, pops: %s, data: %s };' % (pm['sr'], json.dumps(pc['credit']), json.dumps(pm['pops'], separators=(',', ':')), json.dumps(pdata)))
out.append('  DR.ENG_BANK_BY_LAYOUT = %s;' % json.dumps(cfg.get('by_layout', {})))
out.append('  DR.ENG_BANK_BY_ENGINE = %s;' % json.dumps(cfg.get('by_engine', {})))
out.append('  DR.ENG_BANK_OPTS = %s;' % json.dumps(cfg.get('opts', {})))
out.append('})();')
open(os.path.join(os.path.dirname(__file__), '..', '..', 'www', 'js', 'engbanks.js'), 'w').write('\n'.join(out) + '\n')
print('banks', len(ids))
